<script setup lang="ts">
import {computed,onMounted,ref} from 'vue'
import AppModal from '@/components/AppModal.vue'
import {demoMode,request} from '@/services/quality'
const items=ref<{id:number;title:string;status:string;attempts:number;created_at:string;retry_at?:string;read_at?:string}[]>([]);const local=ref(false);const error=ref('');const message=ref('');const open=ref(false)
const page=ref(1);const last=ref(1);const status=ref('');const retryId=ref(0);const retryOpen=ref(false);const busy=ref(false);const selectedId=ref(0)
async function retry(){busy.value=true;try{await request('/notifications/'+retryId.value+'/retry','POST');retryOpen.value=false;await load()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function markRead(){try{await request('/notifications/'+selectedId.value+'/read','POST');open.value=false;await load()}catch(e){error.value=(e as Error).message}}
const labels:Record<string,string>={pending:'En attente d’envoi',sent:'Accepté par le transport email',failed:'Échec — nouvelle tentative prévue',simulated:'Simulé — aucun email envoyé'}
const links=computed(()=>{const matches=message.value.match(/https?:\/\/[^\s]+/g)||[];return matches.flatMap(s=>{try{const u=new URL(s);return ['/verify-email','/reset-password','/invitation','/internal-invitation'].includes(u.pathname)?[{path:u.pathname+u.hash,label:u.pathname==='/verify-email'?'Ouvrir la vérification fictive':u.pathname==='/reset-password'?'Ouvrir le renouvellement fictif':'Ouvrir l’invitation fictive'}]:[]}catch{return[]}})})
async function load(){try{const d=await request<{data:typeof items.value;local_inbox:boolean;last_page?:number}>('/notifications?'+new URLSearchParams({page:String(page.value),...(status.value?{status:status.value}:{})}));items.value=d.data;local.value=d.local_inbox;last.value=d.last_page||1}catch(e){error.value=(e as Error).message}}
async function read(id:number){selectedId.value=id;error.value='';message.value='Consultez le statut de livraison dans la liste. Aucun lien secret n’est affiché hors boîte de test locale.';try{if(local.value)message.value=(await request<{message:string}>('/notifications/'+id+'/preview')).message;open.value=true}catch(e){error.value=(e as Error).message}}
onMounted(()=>{if(!demoMode)load()})
</script>
<template><section class="page erp-page"><div class="page-heading compact"><div><p class="eyebrow">MODULE 01 · NOTIFICATIONS</p><h1>Notifications & livraison</h1><p class="page-subtitle">Un événement enregistré ne signifie pas qu’un email a été reçu.</p></div><button v-if="!demoMode" class="button secondary" @click="load">Actualiser</button></div><p v-if="demoMode" class="panel form-body">Les notifications sont disponibles dans l’aperçu API.</p><template v-else><p v-if="error" role="alert" class="alert error">{{error}}</p><p v-if="local" class="review-note">Boîte de test locale activée : les liens peuvent être essayés ici sans prouver la propriété réelle d’une adresse email. Cette fonction est interdite en production.</p><div class="panel"><form class="table-toolbar" @submit.prevent="page=1;load()"><label>État email<select v-model="status"><option value="">Tous les états</option><option v-for="(label,key) in labels" :key="key" :value="key">{{label}}</option></select></label><button class="button secondary">Filtrer</button></form><div class="table-scroll"><table><thead><tr><th>ÉVÉNEMENT</th><th>ÉTAT EMAIL</th><th>TENTATIVES</th><th>ACTION</th></tr></thead><tbody><tr v-for="n in items" :key="n.id"><td>{{n.title}}<span class="table-subtitle">{{n.created_at}} UTC</span></td><td>{{n.status==='failed'&&n.attempts>=5?'Échec définitif après 5 tentatives':labels[n.status]||n.status}}<span v-if="n.retry_at&&n.status==='failed'&&n.attempts<5" class="table-subtitle">Reprise prévue : {{n.retry_at}} UTC</span></td><td>{{n.attempts}}</td><td><button class="button secondary small" @click="read(n.id)">{{local?'Ouvrir le message de test':'Voir la notification'}}</button><button v-if="n.status==='failed'&&n.attempts<5" class="button secondary small" @click="retryId=n.id;retryOpen=true">Planifier une reprise</button><span v-if="n.read_at" class="table-subtitle">Lue</span></td></tr><tr v-if="!items.length"><td colspan="4" class="empty-state">Aucune notification pour ce compte.</td></tr></tbody></table></div><div class="panel-heading"><button class="button secondary" :disabled="page<=1" @click="page--;load()">Précédent</button><span>{{page}} / {{last}}</span><button class="button secondary" :disabled="page>=last" @click="page++;load()">Suivant</button></div></div></template><AppModal v-model="open" :title="local?'Message de test local':'Notification'"><div class="form-body"><p v-if="local" class="module-disclaimer">SIMULATION UNIQUEMENT — ne vaut pas livraison email.</p><p class="document-content">{{message}}</p><div class="module-links"><RouterLink v-for="link in links" :key="link.path" :to="link.path" class="button primary" @click="open=false">{{link.label}}</RouterLink></div></div><template #footer><button class="button secondary" @click="open=false;message=''">Fermer</button><button class="button primary" @click="markRead">Marquer comme lue</button></template></AppModal><AppModal v-model="retryOpen" title="Planifier une nouvelle tentative ?" :busy="busy"><div class="form-body"><p>La reprise sera proposée au worker d’envoi. Aucun email n’est déclaré envoyé avant l’acceptation par le transport. La limite reste fixée à cinq tentatives.</p><p v-if="error" class="alert error" role="alert">{{error}}</p></div><template #footer><button class="button secondary" :disabled="busy" @click="retryOpen=false">Annuler</button><button class="button primary" :disabled="busy" @click="retry">Confirmer</button></template></AppModal></section></template>
